#include <bits/stdc++.h>
using namespace std;

/**
 * Write a function to remove everything except alphanumeric characters from a string.
 * > removeSplchar(string("python  @#&^%$*program123"))
 * string("pythonprogram123")
 * > removeSplchar(string("python %^$@!^&*()  programming24%$^^()    language"))
 * string("pythonprogramming24language")
 * > removeSplchar(string("python   ^%&^()(+_)(_^&67)                  program"))
 * string("python67program")
 */
string removeSplchar(string text) {
    // Initialize an empty result string
    string result = "";

    // Loop through each character in the input string
    for (char c : text) {
        // Check if the character is alphanumeric using isalnum function
        if (isalnum(c)) {
            // If it's alphanumeric, append it to the result string
            result += c;
        }
    }

    // Return the final result string containing only alphanumeric characters
    return result;
}
