if (n < 0 || k < 0 || k > n) {
        return -1; // Invalid input
    }

    double factorial_n = 1;
    for (int i = 1; i <= n; ++i) {
        factorial_n *= i;
    }

    double factorial_k = 1;
    for (int i = 1; i <= k; ++i) {
        factorial_k *= i;
    }

    double factorial_n_minus_k = 1;
    for (int i = 1; i <= (n - k); ++i) {
        factorial_n_minus_k *= i;
    }

    double combination = factorial_n / (factorial_k * factorial_n_minus_k);
    double probability_part = pow(p, k) * pow(1 - p, n - k);

    double prob = combination * probability_part;

    return prob;

